import pyomo.environ as pyo

DATA = {
    "products": ["thin", "stubby"],
    "resources": ["shaping", "baking"],
    # usage[resource][product] = minutes of that resource per jar
    "usage": {
        "shaping": {"thin": 50, "stubby": 30},
        "baking":  {"thin": 90, "stubby": 150},
    },
    # available[resource] = minutes available per week
    "available": {
        "shaping": 3000,
        "baking": 4000,
    },
    # profit[product] = dollars per jar
    "profit": {
        "thin": 5,
        "stubby": 9,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # ----- Sets -----
    model.P = pyo.Set(initialize=d["products"], ordered=True)
    model.R = pyo.Set(initialize=d["resources"], ordered=True)

    # ----- Variables -----
    # x[p] = number of jars of product p made per week (indivisible -> integer)
    model.x = pyo.Var(model.P, domain=pyo.NonNegativeIntegers, bounds=(0, None))

    # ----- Objective: maximize total profit -----
    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # ----- Constraints: one per resource (usage must be <= availability) -----
    def resource_rule(m, r):
        return sum(d["usage"][r][p] * m.x[p] for p in m.P) <= d["available"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model
